  const candidates=(D.travelEvents||[]).filter(e=>Math.random()<e.chance);if(candidates.length){const e=rn(candidates);if(e.cost&&s.cash>=e.cost){s.cash-=e.cost;logTransaction(-e.cost,'Travel',e.title,{account:'Checking'})}applyEffects(e.effects||{});extra=` ${e.text}`}
  const label=travelLabel(mode);s.travelHistory.unshift({id:uid(),age:s.age,activity:a.id,tripLabel:a.label,destination:place,detail:detail+extra,companion:mode,companionLabel:label,cost});if(s.travelHistory.length>80)s.travelHistory.length=80;
