  $('housingBtn').onclick=()=>{const key=$('housingSelect').value,h=D.housing[key];if(s.age<h.minAge)return msg('housingMessage','Too young for that housing option.');if(key==='parents'){s.primaryPropertyId=null;s.housing='parents';syncLegacyPropertyFields();log(`Age ${s.age}: Moved in with family.`);commit();return}if(!h.owned){s.primaryPropertyId=null;s.housing=key;syncLegacyPropertyFields();log(`Age ${s.age}: Moved into ${h.name}.`);commit();return}const price=housingMarketPrice(key),mort=D.balance.yearly.finance.mortgage,down=Math.round(price*mort.downPayment);if((s.credit||0)<620)return msg('housingMessage','Credit 620+ required.');if(s.cash<down)return msg('housingMessage',`Need ${money(down)} for the down payment.`);s.cash-=down;logTransaction(-down,'Housing',`${h.name} down payment — ${s.location}`,{account:'Checking'});const p={id:uid(),key,name:h.name,location:s.location,purchasePrice:price,marketValue:price,purchaseAge:s.age,condition:100,upgrades:[],mortgageBalance:price-down,mortgageRate:s.economy.interest+mort.rateSpread,mortgageYearsRemaining:mort.termYears};s.properties.push(p);s.primaryPropertyId=p.id;s.housing=key;syncLegacyPropertyFields();s.credit=Math.max(300,s.credit-12);s.stats.homesOwned++;recordLife('homePurchase',`Bought ${h.name}`,{price,down,location:s.location,propertyId:p.id});log(`Age ${s.age}: Bought a ${h.name} in ${s.location} for ${money(price)} with ${money(down)} down.`);msg('housingMessage',`Property purchased. You now own ${s.properties.length} propert${s.properties.length===1?'y':'ies'}. Mortgage: ${money(p.mortgageBalance)} at ${(p.mortgageRate*100).toFixed(2)}%.`);commit()};
  $('payMortgageBtn').onclick=()=>{const p=currentProperty();if(!(p?.mortgageBalance>0))return msg('housingMessage','Your primary residence has no mortgage balance.');const a=Math.min(s.cash,p.mortgageBalance,transferOption('mortgageAmountSelect','mortgageCustomAmount',p.mortgageBalance));if(a<=0)return msg('housingMessage','Choose a valid payment amount and make sure you have enough cash.');s.cash-=a;p.mortgageBalance=Math.max(0,p.mortgageBalance-a);logTransaction(-a,'Housing',`Extra mortgage payment — ${p.name||D.housing[p.key]?.name}`,{account:'Checking'});if(p.mortgageBalance<=0){p.mortgageBalance=0;p.mortgageYearsRemaining=0;msg('housingMessage','Mortgage paid off!')}else msg('housingMessage',`${money(a)} paid toward the mortgage. ${money(p.mortgageBalance)} remaining.`);syncLegacyPropertyFields();commit()};
  $('sellHomeBtn').onclick=()=>{const p=currentProperty();if(!p)return msg('housingMessage','You do not currently have an owned primary residence to sell.');sellPropertyById(p.id)};
  if($('repairPropertyBtn'))$('repairPropertyBtn').onclick=()=>{const p=currentProperty();if(!p)return msg('housingMessage','You need a primary owned property to repair.');if(Number(p.condition||100)>=99.5)return msg('housingMessage','Your primary property is already in excellent condition.');const cost=propertyRepairCost(p);if(s.cash<cost)return msg('housingMessage',`Need ${money(cost)} for the repair work.`);s.cash-=cost;logTransaction(-cost,'Housing',`Repairs — ${p.name||D.housing[p.key]?.name||'Property'} — ${p.location}`,{account:'Checking'});const before=Math.round(p.condition||100),gain=Math.max(8,Number(D.housingEconomy?.maintenanceConditionRecovery||18));p.condition=clamp(Number(p.condition||100)+gain);recordLife('propertyRepair',`Repaired ${p.name||D.housing[p.key]?.name||'property'}`,{propertyId:p.id,cost,conditionBefore:before,conditionAfter:Math.round(p.condition)});msg('housingMessage',`Repairs completed for ${money(cost)} • Condition ${before}% → ${Math.round(p.condition)}%.`);commit()};if($('homeUpgradeBtn'))$('homeUpgradeBtn').onclick=()=>{const p=currentProperty(),h=p&&D.housing[p.key];if(!p||!h?.owned)return msg('housingMessage','You need an owned primary residence before adding improvements.');const key=$('homeUpgradeSelect').value,u=D.homeUpgrades?.[key];if(!u)return;if((p.upgrades||[]).includes(key))return msg('housingMessage','That improvement is already installed on this property.');if(s.cash<u.cost)return msg('housingMessage',`Need ${money(u.cost)}.`);s.cash-=u.cost;logTransaction(-u.cost,'Housing',`${u.name} — ${p.location}`,{account:'Checking'});p.upgrades.push(key);const gain=Math.max(Number(u.cost||0),Number(u.valueBoost||0));p.marketValue=Math.round(propertyValue(p)+gain);p.condition=clamp((p.condition||100)+4);syncLegacyPropertyFields();stat('happiness',u.happiness||0);recordLife('homeUpgrade',`Added ${u.name}`,{upgrade:key,cost:u.cost,valueGain:gain,propertyId:p.id});addMemory(`🏠 ${u.name}`,`Improved ${h.name} for ${money(u.cost)}; property value +${money(gain)}`,'housing');queueExperience('🏠 Home Improvement',`You completed ${u.name} for ${money(u.cost)}. The property gained ${money(gain)} in value.`,'The renovation became part of my home story.');msg('housingMessage',`${u.name} completed • Cost ${money(u.cost)} • Property value +${money(gain)}.`);commit()};
