  $('argueBtn').onclick=()=>{if(!s.partner)return;const r=R.argue;if(!actionCost('partnerConflict',r.ap))return;const good=Math.random()<Math.max(.05,Math.min(.95,r.baseSuccess+s.skills.communication/180));if(good){s.partner.quality=clamp(s.partner.quality+r.qualitySuccess);stat('stress',r.stressSuccess);log(`I talked through a problem with ${s.partner.name}.`);msg('relationshipMessage','You talked through the problem.')}else{s.partner.quality=clamp(s.partner.quality+r.qualityFail);stat('stress',r.stressFail);log(`I got into an argument with ${s.partner.name}.`);msg('relationshipMessage','The conversation turned into an argument.')}commit()};
  $('proposeBtn').onclick=()=>{if(!s.partner)return msg('relationshipMessage','You need a partner first.');const r=R.propose,miss=missingRequirements(r.requirements||[]);if(miss.length)return msg('relationshipMessage',`Locked: ${miss.join(' • ')}.`);const accepted=Math.random()<r.baseSuccess+s.partner.quality/220+s.social/500;if(accepted){s.relationship='Engaged';s.partner.relation='Fiancé';addNpcRelationshipHistory(s.partner,'relationship',`Became engaged to ${s.name}`);log(`Age ${s.age}: ${s.partner.name} accepted your proposal.`);msg('relationshipMessage','You are engaged!')}else{s.partner.quality=clamp(s.partner.quality+r.declineQuality);msg('relationshipMessage','The proposal was declined.')}commit()};
